    border-radius: 12px;
    font-size: 0.8rem;
    cursor: pointer;
    transition: background 0.15s;
}

.reaction-badge:hover {
    background: #dce6f8;
}

.thread-link {
    margin-top: 6px;
    font-size: 0.8rem;
    color: #1264a3;
    cursor: pointer;
    font-weight: 500;
