    line-height: 1;
    padding: 4px 8px;
    border-radius: 4px;
}

.close-btn:hover {
    background: #eee;
}

.thread-root-message {
    padding: 12px 16px;
    border-bottom: 1px solid #e8e8e8;
    background: #f0f4ff;
}

.thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
}

.no-channel-selected {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #999;
    font-size: 1.1rem;
}

